<script setup lang="ts">
import { DatePicker } from '../../src/date-picker';
import { Popover } from '../../src/popover';
import PlainPart from './PlainPart.vue';

defineProps<{
  hasElementSlot: boolean;
  active: boolean;
  onPartRender: () => void;
  onInnerRender: () => void;
}>();
</script>

<template>
  <DatePicker.Root open>
    <DatePicker.Trigger>Open</DatePicker.Trigger>
    <Popover.Portal>
      <DatePicker.Positioner
        v-if="hasElementSlot"
        data-testid="positioner"
        :data-active="active"
        @vue:mounted="onPartRender"
        @vue:updated="onPartRender"
      >
        <template #element="{ props, elementRef }">
          <section v-bind="props" :ref="elementRef">
            <PlainPart data-testid="inner" @vue:mounted="onInnerRender" @vue:updated="onInnerRender"
              >Content</PlainPart
            >
          </section>
        </template>
      </DatePicker.Positioner>
      <DatePicker.Positioner
        v-else
        data-testid="positioner"
        :data-active="active"
        @vue:mounted="onPartRender"
        @vue:updated="onPartRender"
      >
        <PlainPart data-testid="inner" @vue:mounted="onInnerRender" @vue:updated="onInnerRender"
          >Content</PlainPart
        >
      </DatePicker.Positioner>
    </Popover.Portal>
  </DatePicker.Root>
</template>
